/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

public static METVendorRebateDiscountValues find(
    METRebateDiscountValue _metVendorRebateDiscountValues ,
    boolean _forupdate = false,
    ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
{
    METVendorRebateDiscountValues metVendorRebateDiscountValues;

    metVendorRebateDiscountValues.selectForUpdate(_forupdate);
    if (_forupdate && _concurrencyModel != ConcurrencyModel::Auto)
    {
        metVendorRebateDiscountValues.concurrencyModel(_concurrencyModel);
    }

    select firstonly metVendorRebateDiscountValues where metVendorRebateDiscountValues.RebateDiscountValue == _metVendorRebateDiscountValues;

    return metVendorRebateDiscountValues;
}

public static boolean exist(METRebateDiscountValue _metVendorRebateDiscountValuesId)
{
    boolean found;

    found = (select firstonly
                 RecId
            from
                 METVendorRebateDiscountValues
             where
                 METVendorRebateDiscountValues.RebateDiscountValue == _metVendorRebateDiscountValuesId).RecId != 0;

    return found;
}
